INSERT INTO `zrd_frm_forums` (`id`, `forum_name`, `forum_desc`, `redirect_url`, `moderators`, `num_topics`, `num_posts`, `last_post`, `last_post_id`, `last_poster`, `last_subject`, `sort_by`, `disp_position`, `cat_id`) VALUES
(5, 'Discussions générales', 'Pour parler de tout et de rien, sur Zordania ou pas...', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 1, 2),
(6, 'Suggestions', 'Nous sommes toujours en quêtes d\'idées nouvelles...', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 2, 2),
(7, 'Entraide', 'Vous avez des questions ? Nous avons des réponses !', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 3, 2),
(8, 'Rapports de bugs', 'Quelque chose ne fonctionne pas ? C\'est ici qu\'il faut le signaler !', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 4, 2),
(9, 'Haute Place', 'Au beau milieu du quartier riche des nobles et des puissants se trouve la Haute Place.\nC\'est ici que les Seigneurs se rencontrent pour y signer des pactes, forger des alliances et parlementer entre Grands de ce monde...', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 0, 1),
(12, 'Hall des Batailles', 'Ce grand bâtiment domine fièrement le quartier riche.\nIl a connu tous les conflits de Zordania : c\'est en son sein qu\'alliés et ennemis se déclarent la guerre ou négocient la paix sous l\'oeil attentif du clergé... parfois il arrive que les Dieux viennent s\'immiscer dans les conflits des mortels.\nLa garde y est bien entendu présente pour éviter tout débordement.', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 1, 1),
(14, 'La Cour des Légendes', 'Les plus illustres bardes viennent ici conter leurs aventures ou raconter des histoires rédigées par de talentueux écrivains.', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 2, 1),
(15, 'Modération', 'Accord sur la modération des forums, réservé aux Gardes et aux Prêtres.', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 2, 4),
(16, 'VIP', 'Toute l\'équipe, ainsi que les sages, les scribes et les nobles', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 1, 4),
(17, 'Suggestions intéressantes', 'Une suggestion à de l\'avenir ? Voyons voir...', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 5, 3),
(18, 'Admin', 'Bah admin quoi', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 0, 4),
(20, 'Bugs à Régler', 'Les bugs à corriger', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 3, 3),
(21, 'Question techniques et Ressources', 'Informations diverses sur le mode de développement, tutoriels, etc .. A lire absolument si vous êtes nouveau !', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 0, 3),
(22, 'Suggestions retenues', 'Les futurs modifications', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 6, 3),
(23, 'Bugs Corrigés', 'Liste des bugs corrigés', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 4, 3),
(24, 'Travaux en Cours', 'Recense les travaux en cours', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 1, 3),
(25, 'News', 'Toutes les actualités RP et gameplay concernant Zordania', NULL, NULL, 1, 1, 1517403361, 1199, 'Zordania', 'Empty!', 1, 0, 2),
(28, 'Topics Archivés', 'Anciens topics', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 0, 6),
(29, 'Bas Quartiers', 'Loin des beaux quartiers et des gens bien pensants se dessinent de sombres ruelles : les bas-quartiers. Bandits, assassins et toute la pègre locale s’y mêlent, se retrouvant dans les multiples troquets, comptoirs aux activités louches et tavernes pour y manigancer les futurs grands complots. Restez chez vous, ou soyez vigilant...', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, 0, 0, 1),
(30, 'Temple des prières', 'Quelque chose vous tracasse? Vous avez peur des oreilles indiscrètes? Seul les dieux entendront votre prières en ce lieu!', NULL, NULL, 0, 0, 0, 0, '', '', 0, 5, 2);
